\label{prop: algcSS differentials}
	The algebraic spectral sequence has the following $d_1$-differentials 
	\begin{align*}
		d_1(v_2^iv_0^jc_6^k\beta^\ell\alpha_1^\epsilon) &\,\dot{=}\, v_2^{i-1}v_0^jc_6^k\beta^\ell\alpha_1^\epsilon b_4\alpha_2 & i\not\equiv 0 \mod 3
	\end{align*}
	for natural numbers $i, j, k, \ell$ and $\epsilon\in \{0,1\}$. There are no other differentials.

Let $\alpha_0, \alpha_1, \alpha_2$ be elements of $\operatorname{Ext}$ such that the Massey product $\langle \alpha_0, \alpha_1, \alpha_2\rangle$ is defined. For each $i$, let $a_i$ be a permanent cycle on the May $E_r$-page which detects $\alpha_i$. Suppose further that 
	\begin{enumerate}
		\item The Massey product $\langle a_0,a_1,a_2\rangle$ is defined on the $E_{r+1}$-page: there are $a_{01}$ and $a_{12}$ such that $d_r(a_{01}) = \overline{a_0}a_1$ and $d_r(a_{12}) = \overline{a_1}a_2$.
		\item If $(m,s,t)$ is the tri-degree of either $a_{01}$ or $a_{12}$, and for for any $m'\geq m$ and $q$ such that $m'-q<m-r$, the differential
			\[
			d_q: E_q^{m', s, t}\to E_q^{m'-q+1, s+1,t}
			\]
			is zero. 
	\end{enumerate}
	Then the element $\overline{a_{01}}a_3+\overline{a_0}a_{12}$ is a permanent cycle and detects an element of $\langle \alpha_0, \alpha_1, \alpha_2\rangle$.

\label{thm: edge homomorphism}
	The edge homomorphism for the Adams-Novikov spectral sequence for $\mathrm{tmf}$ is a map 
	\[
	\pi_*\mathrm{tmf}\to MF_*(\mathbb{Z}_{(3)}):= MF_*\otimes\mathbb{Z}_{(3)}
	\]
	where $MF_*$ is the ring of classical integral modular forms. The image of this map contains $c_4, c_6, 3\Delta, 3\Delta^2$ and $\Delta^3$. Moreover, this map is a rational isomorphism.

\label{prop: d2b4}
There is an Adams $d_2$-differential
\begin{equation}\label{eq: d2b4}
d_2(b_4)\,\dot{=}\, \alpha_2.
\end{equation}

There is an Adams $d_2$-differential 
	\begin{equation}\label{eq: d2v0v2}
	d_2(v_0v_2)\,\dot{=}\,c_6\alpha_1.
	\end{equation}

In $\pi_*\mathrm{tmf}$, one has that $c_6\beta=0$. Consequently, there is an Adams $d_2$-differential 
	\begin{equation}\label{eq:d2v2alpha2}
	d_2(v_2\alpha_2)\,\dot{=}\, c_6\beta.
	\end{equation}

There is a $d_2$-differential 
	\begin{equation}\label{eq: d2b4v2^2}
	d_2(b_4v_2^2)\,\dot{=}\, v_2^2\alpha_2.
	\end{equation}
	as well as the $d_2$-differential 
	\begin{equation}\label{eq:d2v0b4v2^2}
	d_2(v_0b_4v_2^2)\, \dot{=}\, v_2c_6b_4\alpha_1 
	\end{equation}

There is the following $d_2$-differential
	\begin{equation}\label{eq: d2v2^2b4alpha2}
	d_2(v_2^2b_4\alpha_2)\, \dot{=}\, v_2c_6b_4\beta.
	\end{equation}

\label{prop: Adams E3}
	The Adams $E_3$-term is given as a module over $\operatorname{Ext}_{A(1)_*}(\mathbb{F}_3)$ as the infinite direct sum of the following types of modules,
	\begin{enumerate}
		\item[Pattern 1'] For all $j\geq 0$, we have the modules 
			\[
			\operatorname{Ext}_{A(1)_*}(\mathbb{F}_3)/(\alpha_2, c_6\beta, c_6\alpha_1)\cdot\{v_2^{3j}, v_2^{3j+1}b_4\}
			\]
		\item[Pattern 2'] For all $j\geq 0$, we have the modules 
			\[
			\operatorname{Ext}_{A(1)_*}(\mathbb{F}_3)/(\alpha_1,\alpha_2, \beta)\cdot \{v_0v_2^{3j}b_4, v_0^2v_2^{3j+1},v_0v_2^{3j+2}, v_0^2v_2^{3j+2}b_4\},
			\]
		and the ring structure is inherited from the Adams $E_2$-term. 
	\end{enumerate}

There is an isomorphism of $\operatorname{Ext}_{A(1)_*}(\mathbb{F}_3)$-modules 
	\begin{equation}\label{eq: Delta cubed decomposition}
	E_3(\mathrm{tmf})\cong \bigoplus_{k\geq 0}M\cdot\{v_2^{9k}\}
	\end{equation}
